1133	/**
1134	 * The rendered-style projection that participates in the parity digest: the
1135	 * probes the lanes must agree on, in full, plus the LABELS of the ones the
1136	 * receipt declares they disagree on. Folding the declared-difference values in
1137	 * would make the two lanes disagree about a difference the receipt already
1138	 * records; dropping the labels would let a probe leave the declaration
1139	 * unnoticed.
1140	 */
1141	function renderedStyleProjection(
1142		evidence: WitnessRenderedStyleEvidence | undefined,
1143		declaredDifferenceLabels: readonly string[],
1144	): unknown {
1145		const differing = new Set(declaredDifferenceLabels);
1146		return {
1147			state: evidence?.state,
1148			agreeing: (evidence?.probes ?? []).filter((probe) => !differing.has(probe.label)),
1149			declaredDifferenceLabels: (evidence?.probes ?? [])
1150				.map((probe) => probe.label)
1151				.filter((label) => differing.has(label)),
1152		};
1153	}
