1295	function assertConsoleErrorInventory(
1296		inventory: WitnessConsoleErrorInventory | undefined,
1297		pinned: readonly WitnessConsoleErrorInventoryEntry[],
1298		label: string,
1299	): void {
1300		const expected = pinned.map((entry) => ({ message: entry.message, count: entry.count }));
1301		if (
1302			inventory === undefined ||
1303			inventory.policy !== 'exact-app-scoped-expected-console-errors' ||
1304			inventory.originPlaceholder !== '{production-static-origin}' ||
1305			!exact(inventory.outsideInventory, []) ||
1306			!exact(inventory.expected, expected) ||
1307			!exact(inventory.observed, expected) ||
1308			inventory.total !== expected.reduce((sum, entry) => sum + entry.count, 0)
1309		)
1310			throw new Error(`Angular Super Productivity console-error inventory differs: ${label}`);
1311	}
