1321			reason: entry.reason,
1322			count: entry.count,
1323		}));
1324		if (
1325			inventory === undefined ||
1326			inventory.policy !== 'exact-app-scoped-expected-failed-requests' ||
1327			!exact(inventory.outsideInventory, []) ||
1328			!exact(inventory.expected, expected) ||
1329			!exact(inventory.observed, expected) ||
1330			inventory.total !== expected.reduce((sum, entry) => sum + entry.count, 0)
1331		)
