1335	/**
1336	 * The per-lane seam membership. Every member is a GET on the one declared
1337	 * origin, every declared member is accounted for as observed or absent, and
1338	 * nothing may sit outside the declaration — including the font-FILE host the
1339	 * application's own service-worker config names but its lazy asset group never
1340	 * reaches for on its own.
1341	 */
1342	function assertMockedSeams(
1343		inventory: WitnessMockedNonLoopbackSeamInventory | undefined,
1344		published: WitnessMockedNonLoopbackSeamEntry[],
1345		label: string,
1346	): void {
1347		const originated = (entry: WitnessMockedNonLoopbackSeamEntry): boolean =>
1348			entry.method === 'GET' &&
1349			entry.path.startsWith(`${WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAM_ORIGIN}/`);
1350		if (
1351			inventory === undefined ||
1352			inventory.policy !== 'exact-app-scoped-mocked-non-loopback-seams' ||
1353			inventory.pathPolicy !== WITNESS_NON_LOOPBACK_QUERY_FREE_PATH_RULE ||
1354			!exact(inventory.outsideInventory, []) ||
1355			inventory.successfulNonLoopback !== 0 ||
1356			inventory.category.length === 0 ||
1357			!inventory.category.every(originated) ||
1358			!exact(inventory.category, published) ||
1359			!exact(inventory.category, WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAMS) ||
1360			inventory.observed.length + inventory.absent.length !== inventory.category.length ||
1361			inventory.observed.some((observation) => observation.requests < 1)
1362		)
1363			throw new Error(`Angular Super Productivity mocked seam inventory differs: ${label}`);
1364	}
