1368	 * nothing else. A run that quietly dropped a property from a probe would be
1369	 * claiming a narrower measurement than the one this schema declares.
1370	 */
1371	function assertRenderedStyles(
1372		evidence: WitnessRenderedStyleEvidence | undefined,
1373		label: string,
1374	): void {
1375		if (
1376			evidence === undefined ||
1377			evidence.state !== 'measured-resolved-styles' ||
1378			evidence.probes.length !== WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.length ||
1379			evidence.probes.some((probe, index) => {
1380				const pinned = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES[index];
1381				return (
1382					pinned === undefined ||
1383					probe.label !== pinned.label ||
1384					probe.selector !== pinned.selector ||
1385					!exact(Object.keys(probe.properties).sort(), [...pinned.properties].sort()) ||
1386					Object.values(probe.properties).some((value) => value.length === 0) ||
1387					probe.width < 0 ||
1388					probe.height < 0
1389				);
1390			})
