1395	/**
1396	 * The published declared differences, checked in both directions across the
1397	 * lane pair: a probe outside the declaration must resolve identically, and a
1398	 * probe inside it must actually differ.
1399	 */
1400	function assertRenderedStyleDifferences(
1401		baseline: WitnessRenderedStyleMeasurement[],
1402		migrated: WitnessRenderedStyleMeasurement[],
1403		declaredDifferences: ReadonlyArray<{ label: string; why: string }>,
1404	): void {
1405		const declared = new Set(declaredDifferences.map((entry) => entry.label));
1406		const probeLabels = new Set<string>(
1407			WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => probe.label),
1408		);
1409		if (
1410			declared.size !== declaredDifferences.length ||
1411			declaredDifferences.some((entry) => !probeLabels.has(entry.label) || entry.why.length === 0)
1412		)
1413			throw new Error('Angular Super Productivity declared style differences are not probes');
1414		for (const [index, probe] of baseline.entries()) {
1415			const other = migrated[index];
1416			if (other === undefined || other.label !== probe.label)
1417				throw new Error('Angular Super Productivity rendered-style lanes are not comparable');
1418			if (declared.has(probe.label) === exact(probe.properties, other.properties))
1419				throw new Error(
1420					`Angular Super Productivity rendered-style declared difference differs: ${probe.label}`,
1421				);
1422		}
1423	}
