1479	/**
1480	 * Leg (b): the task-list reorder, checked as a rule rather than against a pinned
1481	 * order. The moved task is named and is in the list, the after-order is a
1482	 * permutation of the before-order that actually changed, and the store the
1483	 * application settled to agrees with the list the page rendered.
1484	 */
1485	function assertDrag(
1486		journey: WitnessAngularSuperProductivityJourney | undefined,
1487		label: string,
1488	): void {
1489		const drag = journey?.drag;
1490		if (
1491			drag === undefined ||
1492			drag.state !== 'measured-task-list-reorder' ||
1493			drag.surface !== ANGULAR_SUPER_PRODUCTIVITY_APP ||
1494			!(WITNESS_REAL_APP_DRAG_SURFACES as readonly string[]).includes(drag.surface) ||
1495			drag.pointer !== 'genuine-dragula-pointer-down-move-up' ||
1496			drag.movedTask.length === 0 ||
1497			!Array.isArray(drag.renderedOrderBefore) ||
1498			!Array.isArray(drag.renderedOrderAfter) ||
1499			!Array.isArray(drag.storeOrderAfter) ||
1500			drag.renderedOrderBefore.length === 0 ||
1501			// The reorder is a permutation: the same multiset in a different order.
1502			drag.renderedOrderBefore.length !== drag.renderedOrderAfter.length ||
1503			[...drag.renderedOrderBefore].sort().join('\n') !==
1504				[...drag.renderedOrderAfter].sort().join('\n') ||
1505			drag.renderedOrderBefore.join('\n') === drag.renderedOrderAfter.join('\n') ||
1506			// The task that moved is one the list actually held before the move.
1507			!drag.renderedOrderBefore.includes(drag.movedTask) ||
1508			// The store and the page agree on where the move left the list.
1509			drag.storeOrderAfter.join('\n') !== drag.renderedOrderAfter.join('\n')
1510		)
1511			throw new Error(`Angular Super Productivity drag evidence differs: ${label}`);
1512	}
