			mockedSeamPolicy: {
				policy: seams?.policy,
				pathPolicy: seams?.pathPolicy,
				outsideInventory: seams?.outsideInventory,
				successfulNonLoopback: seams?.successfulNonLoopback,
				members: seams?.category.length,
