/**
 * The Super Productivity Witness calibration driver.
 *
 * There is no published journey for this application yet, and pinning one
 * before the live DOM has been read is what the TinyTranslator rounds spent
 * four passes undoing. This drives ONE lane of the bound production-static
 * output through the same host the proof will use, asks the page a list of
 * candidate questions, and prints every answer — including the refusals, which
 * are the measurement when a candidate is wrong.
 *
 * It publishes nothing, asserts nothing of its own, and is not part of any
 * receipt. Its only output is stdout.
 */

import { readFileSync } from 'node:fs';
import { basename, join, resolve } from 'pathe';
import { box, runBoxes } from '@async/witness';
import { joinURL } from 'ufo';
import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
import { WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES } from '../../../core/src/receipts/witness-angular-super-productivity.ts';
import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
import { startStaticServer } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');

/**
 * The two bound lanes, exactly as the schema names them: the era lane is the
 * retained tree the u21 digest correction was recomputed from, and the migrated
 * lane is the offline-faithful rebuild u23 published.
 */
const laneRoots = {
	baseline: join(
		root,
		'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
	),
	migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25'),
} as const;

const VIEWPORT = { width: 1280, height: 900 } as const;

/**
 * The route the driver deep-links to.
 *
 * The bare document was measured first and records its navigation as `#/`,
 * which is not one of the nine routes the application declares — the router
 * renders the work view for it through the wildcard, and a recorded `#/` would
 * be a navigation the application did not name. Deep-linking the declared route
 * is what makes the recorded navigation a declared one.
 */
const INITIAL_ROUTE = '/#/work-view';

/**
 * The candidate selectors, read out of the application's own templates rather
 * than guessed: the shell, the work view, the add-task surface, the task list
 * and the two controls the time-tracking and theme legs would be anchored on.
 * Each is asked for as a count, so a candidate that does not resolve reports
 * zero rather than ending the pass.
 */
const CANDIDATES = [
	'main-header',
	'main-header .project-settings-btn',
	'mat-drawer-container',
	'side-nav',
	// Corrected in the u20c2a round. The first calibration pass asked for
	// `work-view-page` because that is what the component's FILE is called; the
	// component's own `selector` is `work-view`, and the earlier pass measured
	// the mistake honestly as zero. The wrong spelling is kept beside the right
	// one so the correction stays visible in the driver rather than only in a
	// note: a reader can see both asked, and the counts say which one the
	// application actually renders.
	'work-view-page',
	'work-view',
	'.work-view-header',
	'add-task-bar',
	'add-task-bar input',
	'task-list',
	'task-list task',
	'task',
	'task .title',
	'task .play-btn',
	'task .drag-handle',
	'.task-list-wrapper',
	'.completed-tasks-heading',
	'backlog',
	'split',
	'banner',
	'mat-progress-bar',
] as const;

/**
 * The observed page record out of the box receipt, narrowed to the four things
 * an exact inventory has to be pinned from: what the console said, what the
 * browser failed to fetch, what the page threw, and where it navigated.
 */
function pageSummary(receiptPath: string): unknown {
	const receipt = JSON.parse(readFileSync(receiptPath, 'utf8')) as {
		boxes?: Array<{ pages?: Array<Record<string, unknown>> }>;
	};
	const page = receipt.boxes?.[0]?.pages?.[0];
	if (page === undefined) return null;
	return {
		consoleMessages: page.consoleMessages,
		pageErrors: page.pageErrors,
		failedRequests: page.failedRequests,
		navigations: page.navigations,
	};
}

export async function calibrateAngularSuperProductivityLane(
	lane: 'baseline' | 'migrated',
): Promise<void> {
	const laneRoot = laneRoots[lane];
	const receiptDir = join(
		root,
		'.versionless/stage/witness-angular-super-productivity-calibrate',
		lane,
	);
	const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
	const host = createPlaywrightWitnessHost({
		chromiumExecutable: join(
			root,
			'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
		),
		contextProfile: 'current-witness',
		viewport: VIEWPORT,
		// The reader is an opt-in and this driver opts in, because reading the
		// store's keys either side of a create is the whole of leg (e).
		indexedDb: 'read-keys',
		// The application's own `index.html` links the Roboto stylesheet, so the
		// seam is answered inside the context with an empty body exactly as the
		// TinyTranslator vertical answers its icon stylesheet. Nothing leaves the
		// machine, and the request is still observed.
		transport: async () => ({
			action: 'fulfill',
			status: 200,
			contentType: 'text/css',
			body: Buffer.alloc(0),
		}),
	});
	const counts: Record<string, number | string> = {};
	let telemetry: unknown;
	let storage: unknown;
	let scroll: unknown;
	const legs: Record<string, unknown> = {};
	const definition = box(`super-productivity-calibrate-${lane}`, async (context) => {
		const page = await context.browser.visit(joinURL(staticServer.origin, INITIAL_ROUTE));
		for (const selector of CANDIDATES) {
			// Asked for as zero: a candidate that genuinely resolves nothing passes
			// and is recorded as absent, and one that resolves reports its actual
			// count in the refusal, which is the measurement being asked for.
			try {
				await context.expect.page.count(page, selector, 0);
				counts[selector] = 0;
			} catch (error: unknown) {
				counts[selector] = (error instanceof Error ? error.message : String(error))
					.split('\n')[0]!
					.trim();
			}
		}
		telemetry = await host.serviceWorkerTelemetry(10_000);
		storage = await host.browserStorageKeys();
		scroll = await host.viewportScroll();

		// Legs (a) and (e), driven here before either is pinned into a journey.
		// Every reading is printed rather than asserted: what this pass is for is
		// finding out what the application does, and an assertion written before
		// the reading exists is a guess with a stack trace.
		const titleProbe = { group: 'task', name: '.task-title', item: '.task-title' } as const;
		const report = async (stage: string): Promise<void> => {
			legs[stage] = {
				indexedDb: await host.indexedDbKeys().then(
					(inventory) => inventory,
					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
				),
				localStorage: await host.browserStorageKeys(),
				taskTitles: await host.groupedText(titleProbe).then(
					(groups) => groups,
					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
				),
				scroll: await host.viewportScroll(),
			};
		};
		legs['renderedStyles'] = await host.renderedStyles(
			WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => ({
				label: probe.label,
				selector: probe.selector,
				properties: [...probe.properties],
			})),
		);
		await report('before-create');
		await page.trackEvents('click', 'input', 'keydown');

		// PM ruling from u20c2i: drive EVERY mutation before the single leg-(e)
		// reload. The after-reload add-task-bar hang the earlier pass hit is a
		// property of the reloaded page, so the two creates, the timer, the drag
		// and the settings change all happen here, and the reload is last.
		const readIcon = async (): Promise<unknown> =>
			host
				.groupedText({ group: 'main-header .play-btn', name: 'mat-icon', item: 'mat-icon' } as const)
				.then(
					(groups) => groups.flatMap((group) => group.items),
					(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
				);
		const readTitles = async (): Promise<unknown> =>
			host.groupedText({ group: 'task', name: '.task-title', item: '.task-title' } as const).then(
				(groups) => groups.map((group) => group.name),
				(error: unknown) => `refused: ${error instanceof Error ? error.message : String(error)}`,
			);
		const cb: Record<string, unknown> = {};
		// Assigned before the drives so a step that throws still leaves every
		// reading taken up to that point in the printed record, rather than losing
		// the whole block to one refusal.
		legs['legs-c-b-d'] = cb;

		await page.type('add-task-bar input', 'Witness calibration task', { redact: false });
		await page.press('add-task-bar input', 'Enter');
		await new Promise<void>((settle) => void setTimeout(settle, 1_500));
		cb['titles-after-first-create'] = await readTitles();
		await page.type('add-task-bar input', 'Witness calibration task two', { redact: false });
		await page.press('add-task-bar input', 'Enter');
		await new Promise<void>((settle) => void setTimeout(settle, 1_000));
		cb['titles-after-second-create'] = await readTitles();
		for (const selector of [
			'main-header .play-btn',
			'task .play-icon-indicator',
			'task .time-wrapper',
			'task .time-wrapper .time-val',
			'task .drag-handle',
			'task .drag-handle.handle-par',
			'.task-list-inner',
			'.task-list-inner[dragula]',
			'task .start-task-btn',
		]) {
			try {
				await context.expect.page.count(page, selector, 0);
				cb[`count:${selector}`] = 0;
			} catch (error: unknown) {
				cb[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
					.split('\n')[0]!
					.trim();
			}
		}
		// Leg (c), re-anchored (u20c2j): the hover-gated per-task `.start-task-btn`
		// is not visible to a click, so the timer is driven through the header's own
		// global play button, whose `mat-icon` flips play_arrow→pause on start and
		// back on stop. Every reading — the icon, the per-task current marker and the
		// store keys — is taken before start, after start and after stop.
		const readStoreKeys = async (): Promise<unknown> =>
			host.indexedDbKeys().then(
				(inv) =>
					inv.databases
						.find((d) => d.name === 'SUP')
						?.stores.find((s) => s.name === 'SUP_STORE')
						?.keys.map((k) => k.key) ?? 'no SUP_STORE',
				(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
			);
		const readCurrentCount = async (selector: string): Promise<number | string> => {
			try {
				await context.expect.page.count(page, selector, 0);
				return 0;
			} catch (error: unknown) {
				return (error instanceof Error ? error.message : String(error)).split('\n')[0]!.trim();
			}
		};
		cb['icon-before-start'] = await readIcon();
		cb['current-before-start'] = await readCurrentCount('task.isCurrent');
		cb['store-before-start'] = await readStoreKeys();
		try {
			await page.click('main-header .play-btn');
			await new Promise<void>((settle) => void setTimeout(settle, 2_000));
			cb['icon-after-header-start'] = await readIcon();
			cb['current-after-header-start'] = await readCurrentCount('task.isCurrent');
			cb['store-after-header-start'] = await readStoreKeys();
			await page.click('main-header .play-btn');
			await new Promise<void>((settle) => void setTimeout(settle, 2_000));
			cb['icon-after-header-stop'] = await readIcon();
			cb['current-after-header-stop'] = await readCurrentCount('task.isCurrent');
			cb['store-after-header-stop'] = await readStoreKeys();
		} catch (error: unknown) {
			cb['time-tracking-error'] = error instanceof Error ? error.message : String(error);
		}
		// Leg (b): the dragula reorder, initiated on the parent drag handle. Two
		// strategies are tried in one pass: drop onto the second task's handle,
		// and — if the order did not change — drag the second task's handle UP
		// onto the first. Every reading is printed.
		cb['order-before-drag'] = await readTitles();
		try {
			await page.drag(
				'task-list:first-of-type task:nth-of-type(1) .drag-handle.handle-par',
				'task-list:first-of-type task:nth-of-type(2)',
				{ steps: 30 },
			);
			await new Promise<void>((settle) => void setTimeout(settle, 1_200));
			cb['order-after-drag-down'] = await readTitles();
			const afterDown = (await readTitles()) as string[];
			if (
				Array.isArray(afterDown) &&
				afterDown.join('\n') === (cb['order-before-drag'] as string[]).join('\n')
			) {
				await page.drag(
					'task-list:first-of-type task:nth-of-type(2) .drag-handle.handle-par',
					'task-list:first-of-type task:nth-of-type(1)',
					{ steps: 30 },
				);
				await new Promise<void>((settle) => void setTimeout(settle, 1_200));
				cb['order-after-drag-up'] = await readTitles();
			}
			cb['indexeddb-after-drag'] = await host
				.indexedDbKeys()
				.then((i) => i, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
		} catch (error: unknown) {
			cb['drag-error'] = error instanceof Error ? error.message : String(error);
		}

		// Leg (d): settings-change. The app exposes NO dark-theme UI control in
		// v2.13.15 (the isDarkMode formly field is commented out), so the real
		// control driven is the project theme colour. Every selector is asked as
		// a count first, then the surface is exercised and the palette custom
		// properties are read before/after. Exploratory: printed, never asserted.
		const dd: Record<string, unknown> = {};
		legs['leg-d'] = dd;
		const paletteProps = [
			'--palette-primary-500',
			'--palette-accent-500',
			'--palette-primary-400',
			'--c-primary',
			'--c-accent',
		];
		const readPalette = async (): Promise<unknown> =>
			host
				.renderedStyles([
					{ label: 'body-palette', selector: 'body', properties: [...paletteProps] },
					{ label: 'drawer-palette', selector: 'mat-drawer-container', properties: [...paletteProps] },
				])
				.then(
					(probes) => probes,
					(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
				);
		try {
			dd['palette-before'] = await readPalette();
			for (const selector of [
				'side-nav',
				'side-nav button[mat-menu-item]',
				'side-nav .tour-addProjectBtn',
				'side-nav mat-expansion-panel',
				'.projects',
			]) {
				try {
					await context.expect.page.count(page, selector, 0);
					dd[`count:${selector}`] = 0;
				} catch (error: unknown) {
					dd[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
						.split('\n')[0]!
						.trim();
				}
			}
			// A keyboard shortcut: `b` toggles the backlog. Read the split state
			// before and after so the effect is measured rather than assumed.
			dd['split-count-before-shortcut'] = await host
				.groupedText({ group: 'split', name: 'split', item: 'split' } as const)
				.then((g) => g.length, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
			await page.press('body', 'b');
			await new Promise<void>((settle) => void setTimeout(settle, 800));
			dd['backlog-count-after-b'] = await host
				.groupedText({ group: 'backlog', name: 'backlog', item: 'backlog' } as const)
				.then((g) => g.length, (e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`);
			await page.press('body', 'w');
			await new Promise<void>((settle) => void setTimeout(settle, 500));
			dd['route-after-w'] = 'see page navigations';
		} catch (error: unknown) {
			dd['leg-d-error'] = error instanceof Error ? error.message : String(error);
		}
		cb['pageErrors-during-cb'] = 'see page summary';

		// (e) The single reload, LAST, after every mutation has been driven.
		await report('after-create');
		await page.reload();
		await new Promise<void>((settle) => void setTimeout(settle, 2_500));
		await report('after-reload');
		legs['after-reload-telemetry'] = await host.serviceWorkerTelemetry(10_000);
		for (const selector of ['task-list', 'task-list task', 'task', 'task .task-title']) {
			try {
				await context.expect.page.count(page, selector, 0);
				legs[`count:${selector}`] = 0;
			} catch (error: unknown) {
				legs[`count:${selector}`] = (error instanceof Error ? error.message : String(error))
					.split('\n')[0]!
					.trim();
			}
		}
		await context.receipt.capture('calibration-complete');
	});
	let status = 'unknown';
	let failure = '';
	let receiptPath = '';
	try {
		const result = await runBoxes({
			root: laneRoot,
			boxes: [
				{
					file: join(laneRoot, 'versionless-runtime.box.ts'),
					relativeFile: 'versionless-runtime.box.ts',
					exportName: 'default',
					box: definition,
				},
			],
			receiptDir,
			assertionTimeoutMs: 10_000,
			fileSystem: witnessNodeFileSystem,
			browser: host.browser,
			headless: true,
		});
		status = result.status;
		failure = result.boxes[0]?.error?.message ?? '';
		receiptPath = result.receiptPath;
	} finally {
		await staticServer.close();
	}
	process.stdout.write(
		`${canonicalize({
			lane,
			status,
			failure,
			receiptPath,
			counts,
			telemetry,
			storage,
			scroll,
			legs,
			page: receiptPath === '' ? null : pageSummary(receiptPath),
			requestOutcomes: host.requestOutcomes(),
			staticPaths: staticServer.requests(),
		})}\n`,
	);
}

export async function main(args = process.argv.slice(2)): Promise<void> {
	const lane = args[0];
	if (lane !== 'baseline' && lane !== 'migrated')
		throw new Error('Super Productivity calibration requires a lane: baseline or migrated');
	await calibrateAngularSuperProductivityLane(lane);
}

if (basename(process.argv[1] ?? '') === 'angular-super-productivity-calibrate-run.ts')
	main().catch((error: unknown) => {
		process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
		process.exitCode = 1;
	});

	});
}

/**
 * The Super Productivity specification.
 *
 * It is deliberately a skeleton with two legs in it rather than the whole
 * journey. The application's surface admits at least five — create, complete,
 * time-track, theme, reload — and the two here are the pair that stand on their
 * own: leg (a) creates a task through the application's own add-task bar, and
 * leg (e) reloads the document and reads the same task back out of the
 * application's own IndexedDB store. Everything a later leg needs is already
 * shaped for it: the legs are separate helpers over one shared measurement
 * scaffold, the checkpoint list is built in journey order rather than assembled
 * at the end, and the scroll reading is taken at every stage, so a leg that
 * lands between (a) and (e) inserts a call rather than rewriting the journey.
 *
 * Two things this specification declares are worth reading as decisions.
 *
 * The IndexedDB reader is opted into, and it is the only application in the
 * corpus that opts in: the persistence claim here is about the application's own
 * localforage store, and the alternative to reading its keys would be inferring
 * persistence from what the page happened to re-render.
 *
 * Drag is NOT declared and is not driven. The application has the strongest
 * drag surface in the corpus and the closed membership list is still not taking
 * it, because membership is earned by a measured drag whose settled result a
 * journey asserts exactly, and this journey drives none.
 */
const SUPER_PRODUCTIVITY_JOURNEY = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY;

/** The migrated build record this proof serves, bound by the sha256 of its bytes. */
const SUPER_PRODUCTIVITY_BOUND_MIGRATED = ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.find(
	(bound) => bound.lane === 'migrated',
);
if (SUPER_PRODUCTIVITY_BOUND_MIGRATED === undefined)
	throw new Error('Super Productivity bound migrated build record is absent');

const angularSuperProductivitySpec: AppSpec = {
	app: ANGULAR_SUPER_PRODUCTIVITY_APP,
	canonicalReceipt: SUPER_PRODUCTIVITY_BOUND_MIGRATED.path,
	/**
	 * The bound record publishes a top-level `digest` over its own content rather
	 * than an `integrity.canonicalDigest`, so the honest binding is the sha256 of
	 * its exact bytes — the same value the receipt schema binds it by.
	 */
	canonicalDigest: SUPER_PRODUCTIVITY_BOUND_MIGRATED.sha256,
	canonicalBinding: 'file-sha256',
	framework: 'angular',
	sources: {
		baseline: '.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
		migrated: '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25',
	},
	/**
	 * Deep-linked rather than opened bare. The bare document records its
	 * navigation as `#/`, which the router resolves through its `**` route onto
	 * the work view — a route the application does not declare, and one the
	 * receipt schema refuses as a recorded navigation. Asking for the declared
	 * route is what makes the recorded navigation a declared one.
	 */
	initialRoute: SUPER_PRODUCTIVITY_JOURNEY.initialRoute,
	viewport: SUPER_PRODUCTIVITY_JOURNEY.viewport,
	consoleErrorInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_CONSOLE_ERRORS,
	failedRequestInventory: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FAILED_REQUESTS,
	mockedNonLoopbackSeams: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_LANE_SEAMS,
	renderedStyleProbes: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES,
	indexedDb: 'read-keys',
	/**
	 * The one seam either lane reaches for: the Roboto stylesheet the
	 * application's own `index.html` links. It is answered in-context with an
	 * empty body, so nothing leaves the machine and the request is still written
	 * down — and the glyphs never arrive, which is the typeface degradation the
	 * journey measures rather than hides.
	 */
	transport: async () => ({
		action: 'fulfill',
		status: 200,
		contentType: 'text/css',
		body: Buffer.alloc(0),
	}),
	journey: async (context, page, _transportEvidence, lifecycle) => {
		if (lifecycle.expectedServiceWorker !== null)
			throw new Error('Super Productivity journey received a service-worker expectation');
		const script = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER.script;
		const checkpoints: WitnessRealServiceWorkerCheckpoint[] = [
			await realServiceWorkerCheckpoint(lifecycle, 'before-interactions', script),
		];
		const measuredRoutes: WitnessMeasuredScrollAbsence['routes'] = [];
		/**
		 * Taken at every stage. The application pins its drawer container to the
		 * viewport and scrolls its own inner panels, so a stage that started
		 * overflowing fails here rather than passing silently unexercised.
		 */
		const measure = async (stage: string): Promise<void> => {
			const extents = await lifecycle.viewportScroll();
			if (
				extents.clientHeight !== SUPER_PRODUCTIVITY_JOURNEY.viewport.height ||
				extents.scrollHeight > extents.clientHeight ||
				extents.scrollY !== 0
			)
				throw new Error(
					`Super Productivity stage overflows the viewport the receipt says it does not: ${stage} ${canonicalize(extents)}`,
				);
			measuredRoutes.push({
				route: stage,
				scrollHeight: extents.scrollHeight,
				clientHeight: extents.clientHeight,
			});
		};
		/** The application's own store, read for its keys and never its values. */
		const storeKeys = async (): Promise<string[]> =>
			witnessIndexedDbStringKeys(
				await lifecycle.indexedDbKeys(),
				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.databaseName,
				WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.storeName,
			);
		const localKeys = async (): Promise<string[]> => {
			const keys = await lifecycle.browserStorageKeys();
			if (keys.sessionStorage.length !== 0)
				throw new Error(
					`Super Productivity wrote session storage the receipt says it does not: ${canonicalize(keys.sessionStorage)}`,
				);
			return [...keys.localStorage].sort();
		};
		/** The rendered task titles in document order, for legs (b) and (e). */
		const readOrder = async (): Promise<string[]> =>
			(await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.taskTitleProbe)).map(
				(group) => group.name,
			);
		/** The single icon the header's own global play button renders, for leg (c). */
		const readHeaderIcon = async (): Promise<string> => {
			const icons = (
				await lifecycle.groupedText(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconProbe)
			).flatMap((group) => group.items);
			if (icons.length !== 1)
				throw new Error(
					`Super Productivity header play button rendered ${icons.length} icons, not one`,
				);
			return icons[0]!;
		};
		await page.trackEvents('click', 'input', 'keydown');

		// The application as it boots: the work view's own host tag — `work-view`,
		// not the component's file name — its two task lists, and no task in
		// either of them. Nothing has been seeded; this application starts empty.
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.hostTag, 1);
		await context.expect.page.count(
			page,
			SUPER_PRODUCTIVITY_JOURNEY.taskList,
			SUPER_PRODUCTIVITY_JOURNEY.taskLists,
		);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 0);
		const renderedStyles = await lifecycle.renderedStyles();
		const keysBeforeJourney = await storeKeys();
		const localStorageKeysBeforeJourney = await localKeys();
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (before the create)`);

		// (a) The create. The add-task bar is configured `[isAddToBacklog]="false"`
		// in the work view's own template, so a title committed with Enter lands in
		// today's list rather than in the backlog — which is what the count below
		// is actually testing, and why it is asserted on `task-list task` rather
		// than on `task` anywhere in the document.
		await page.type(
			SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
			{ redact: false },
		);
		await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 1);
		await context.expect.page.text(
			page,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitle,
			SUPER_PRODUCTIVITY_JOURNEY.taskTitleText,
		);
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the create)`);

		// A second task, so leg (b) has a list to reorder. It lands below the
		// first, and that first-created-on-top order is where leg (b) begins.
		await page.type(
			SUPER_PRODUCTIVITY_JOURNEY.addTaskInput,
			SUPER_PRODUCTIVITY_JOURNEY.secondTaskTitleText,
			{ redact: false },
		);
		await page.press(SUPER_PRODUCTIVITY_JOURNEY.addTaskInput, 'Enter');
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
		const renderedOrderBefore = await readOrder();
		if (
			canonicalize(renderedOrderBefore) !==
			canonicalize(SUPER_PRODUCTIVITY_JOURNEY.reorder.renderedOrderBefore)
		)
			throw new Error(
				`Super Productivity created list differs from the pinned before-order: ${canonicalize(renderedOrderBefore)}`,
			);
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the second create)`);

		// (c) Time tracking, anchored on the header's own global play button. The
		// per-task start button is hover-gated and the accrued value is sub-minute
		// (both recorded as non-claims on the re-anchor constant), so the anchor is
		// the header button icon: it flips play_arrow to pause on start with one
		// task made current, and back to play_arrow on stop with it cleared. A
		// settled anchor read off the DOM, never a timing.
		const iconBeforeStart = await readHeaderIcon();
		if (iconBeforeStart !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconBeforeStart)
			throw new Error(`Super Productivity header icon before start differs: ${iconBeforeStart}`);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 0);
		await page.click(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.playButton);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 1);
		const iconAfterStart = await readHeaderIcon();
		if (iconAfterStart !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconAfterStart)
			throw new Error(`Super Productivity header icon after start differs: ${iconAfterStart}`);
		await page.click(SUPER_PRODUCTIVITY_JOURNEY.timeTracking.playButton);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.timeTracking.currentTask, 0);
		const iconAfterStop = await readHeaderIcon();
		if (iconAfterStop !== SUPER_PRODUCTIVITY_JOURNEY.timeTracking.iconAfterStop)
			throw new Error(`Super Productivity header icon after stop differs: ${iconAfterStop}`);
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after time tracking)`);

		// (b) The reorder. A genuine dragula pointer drag on the SECOND task's own
		// parent drag handle, dropped up onto the first task, reverses the pair. The
		// down-drag leaves the order unchanged and is not used.
		await page.drag(
			SUPER_PRODUCTIVITY_JOURNEY.reorder.dragHandle,
			SUPER_PRODUCTIVITY_JOURNEY.reorder.dropTarget,
			{ steps: SUPER_PRODUCTIVITY_JOURNEY.reorder.steps },
		);
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
		const renderedOrderAfter = await readOrder();
		if (
			canonicalize(renderedOrderAfter) !==
			canonicalize(SUPER_PRODUCTIVITY_JOURNEY.reorder.renderedOrderAfter)
		)
			throw new Error(
				`Super Productivity reordered list differs from the pinned after-order: ${canonicalize(renderedOrderAfter)}`,
			);
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the reorder)`);
		checkpoints.push(await realServiceWorkerCheckpoint(lifecycle, 'after-interactions', script));

		// (e) A real document reload. There is no backend: the two tasks and the
		// order the drag settled them into are in the application's own IndexedDB
		// store, and what comes back — read off the re-rendered list — is the store
		// list, which is what makes it the store's own agreement with the drag.
		await page.reload();
		await context.expect.page.count(page, SUPER_PRODUCTIVITY_JOURNEY.taskListTask, 2);
		const storeOrderAfter = await readOrder();
		if (canonicalize(storeOrderAfter) !== canonicalize(renderedOrderAfter))
			throw new Error(
				`Super Productivity store order after reload differs from the rendered reorder: ${canonicalize(storeOrderAfter)}`,
			);
		const keysAfterJourney = await storeKeys();
		const localStorageKeysAfterJourney = await localKeys();
		await measure(`${SUPER_PRODUCTIVITY_JOURNEY.initialRoute} (after the online reload)`);
		checkpoints.push(
			await realServiceWorkerCheckpoint(lifecycle, 'after-online-reload', script),
		);
		// The census is the persistence claim. Committing one task adds the four
		// state documents the application writes for its default project and takes
		// nothing away, and the reload changes neither list — which is what makes
		// the re-rendered title a read out of the store rather than a survival of
		// the page.
		if (
			canonicalize(keysBeforeJourney) !==
				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.keysBeforeJourney) ||
			canonicalize(keysAfterJourney) !==
				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.keysAfterJourney) ||
			canonicalize(localStorageKeysBeforeJourney) !==
				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.localStorageKeysBeforeJourney) ||
			canonicalize(localStorageKeysAfterJourney) !==
				canonicalize(SUPER_PRODUCTIVITY_JOURNEY.localStorageKeysAfterJourney)
		)
			throw new Error(
				`Super Productivity key census differs from the pinned measurement: ${canonicalize({
					keysBeforeJourney,
					keysAfterJourney,
					localStorageKeysBeforeJourney,
					localStorageKeysAfterJourney,
				})}`,
			);
		await context.expect.page.outcome(page, {
			events: { input: { atLeast: 1 }, keydown: { atLeast: 1 } },
		});
		await clean(
			context,
			page,
			SUPER_PRODUCTIVITY_JOURNEY.navigations,
			lifecycle.expectedConsoleErrors,
			lifecycle.expectedFailedRequests,
		);
		// Anchored on the probe both lanes agree on rather than on the document
		// body, whose family list genuinely differs across the lift. The reasoning
		// is in the schema beside the constant.
		const typefaceProbe = renderedStyles.find(
			(probe) => probe.label === WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE,
		);
		const resolvedFontFamily = typefaceProbe?.properties['font-family'];
		if (resolvedFontFamily === undefined || resolvedFontFamily.length === 0)
			throw new Error('Super Productivity typeface probe resolved no font family');
		const applicationJourney: WitnessAngularSuperProductivityJourney = {
			typeface: {
				state: 'measured-typeface-degradation',
				cause: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_DEGRADATION_CAUSE,
				fontFaceDeclared: resolvedFontFamily.includes(
					WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE,
				),
				resolvedFontFamily,
				masked: false,
			},
			persistence: {
				store: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.store,
				databaseName: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.databaseName,
				storeName: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE.storeName,
				backend: 'none',
				stubbed: false,
				driverInUse: SUPER_PRODUCTIVITY_JOURNEY.driverInUse,
				keysBeforeJourney,
				keysAfterJourney,
				localStorageKeysBeforeJourney,
				localStorageKeysAfterJourney,
				survivesOnlineReload: true,
			},
			drag: {
				state: 'measured-task-list-reorder',
				surface: ANGULAR_SUPER_PRODUCTIVITY_APP,
				pointer: 'genuine-dragula-pointer-down-move-up',
				movedTask: SUPER_PRODUCTIVITY_JOURNEY.reorder.movedTask,
				renderedOrderBefore,
				renderedOrderAfter,
				storeOrderAfter,
			},
			timeTracking: {
				state: 'measured-task-time-tracking',
				control: 'main-header .play-btn mat-icon',
				iconBeforeStart,
				iconAfterStart,
				iconAfterStop,
				currentTasksOnStart: 1,
				currentTasksOnStop: 0,
			},
		};
		return {
			assertions: [
				'the work view rendered on the application own declared `#/work-view` route, under its own `work-view` host tag, with two task lists and no task in either',
				'a task created through the application own add-task bar by typing a title and committing it with Enter, landing in today list rather than in the backlog',
				'the created task rendered in the task list with the typed title read back off the page',
				'a second task created the same way, the two rendering first-created on top, which is the order leg (b) reorders from',
				'leg (c): the header own global play button flipping its icon from play_arrow to pause on start with one task made current, and back to play_arrow on stop with the current task cleared',
				'leg (b): a genuine dragula pointer drag on the second task own parent handle, dropped up onto the first, reversing the pair into a real permutation of the order before the move',
				'the application own IndexedDB store read for its KEYS either side of the journey, adding the four state documents the application writes for its default project and removing none',
				'the two tasks surviving a real document reload in the drag-settled order, read back off the re-rendered list — the store agreeing with the drag — with the store census unchanged',
				'a real ngsw registered, activated and controlling the page at all three checkpoints, with the worker scripts the build shipped byte-identical either side of the run',
				'the linked Roboto stylesheet answered in-context, with the resolved family measured rather than assumed',
				'clean page',
			],
			offlineEvidence: { state: 'not-applicable' },
			realServiceWorker: {
				script,
				shippedWorkerFiles: WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER.shippedWorkerFiles,
				checkpoints,
			},
			renderedStyles,
			applicationJourney,
			scrollAbsence: {
				state: 'measured-no-overflowing-document',
				viewport: { ...SUPER_PRODUCTIVITY_JOURNEY.viewport },
				routes: measuredRoutes,
				documentOverflow:
					'the application pins its drawer container to the viewport and gives the task lists their own overflow, so no stage of the journey produces a scrollable document',
				claimed: false,
			},
		};
	},
};
apps.push(angularSuperProductivitySpec);

