// Set the formly title input value and dispatch input — only if present.
// The value is set via the native setter + input event rather than
// char-by-char press, so a missing input costs one bounded count rather
// than one interaction timeout per character.
const titleInput = 'dialog-create-project input:not([type=color])';
if ((await actualCount(titleInput)) > 0) {
	dd['title-set-result'] = await page.evaluate(
		`(() => {
			const input = document.querySelector('dialog-create-project input:not([type=color])');
			if (!input) return 'no title input';
			const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
			setter.call(input, 'Witness leg-d project');
			input.dispatchEvent(new Event('input', { bubbles: true }));
			input.dispatchEvent(new Event('change', { bubbles: true }));
			return input.value;
		})()`,
	);
	await new Promise<void>((settle) => void setTimeout(settle, 500));
